-- Module 16: tenant-safe quotation lifecycle, discount approvals, revisions, shares, and conversions.
insert into public.permissions(key,domain,action,description) values
('quotations.read','quotations','read','View quotations and quotation history'),
('quotations.manage','quotations','manage','Create and revise quotations'),
('quotations.send','quotations','send','Send and share quotations'),
('quotations.convert','quotations','convert','Convert accepted quotations')
on conflict(key) do update set domain=excluded.domain,action=excluded.action,description=excluded.description;

update public.module_definitions set configuration_schema='{"properties":{"validity_days":{"type":"integer","label":"Default validity (days)","minimum":1,"maximum":365,"default":30},"discount_approval_percentage":{"type":"number","label":"Discount approval above (%)","minimum":0,"maximum":100,"default":10},"discount_approver_role":{"type":"string","label":"Discount approver role","default":"manager"}},"additionalProperties":false}'::jsonb where key='quotations';
insert into public.module_dependencies(module_key,dependency_module_key) values('quotations','product_catalog') on conflict do nothing;

create function private.install_quotation_permissions(requested_organization_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.role_permissions(role_id,permission_id) select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager','staff') and permission.key in('quotations.read','quotations.manage','quotations.send') on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id) select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager') and permission.key='quotations.convert' on conflict do nothing;
end;$$;
create function private.handle_main_branch_quotation_permissions() returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main' then perform private.install_quotation_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzzzzzzz_install_quotation_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_quotation_permissions();
select private.install_quotation_permissions(id) from public.organizations;

create table public.quotation_number_counters(organization_id uuid not null references public.organizations(id) on delete cascade,year integer not null,last_number integer not null default 0,primary key(organization_id,year));
create table public.quotations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null,quotation_number text not null,revision_number integer not null default 0 check(revision_number>=0),revision_of_id uuid,customer_id uuid not null,assigned_salesperson_id uuid not null,status text not null default'draft' check(status in('draft','sent','accepted','rejected','expired','converted')),approval_status text not null default'not_required' check(approval_status in('not_required','pending','approved','rejected','cancelled')),approval_request_id uuid references public.approval_requests(id),valid_until date not null,notes text check(char_length(notes)<=4000),terms text check(char_length(terms)<=8000),subtotal numeric(16,4) not null default 0 check(subtotal>=0),discount_total numeric(16,4) not null default 0 check(discount_total>=0),tax_total numeric(16,4) not null default 0 check(tax_total>=0),total numeric(16,4) not null default 0 check(total>=0),converted_sale_id uuid,converted_sales_order_id uuid,created_by uuid not null references auth.users(id),sent_at timestamptz,accepted_at timestamptz,rejected_at timestamptz,converted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,quotation_number,revision_number),foreign key(branch_id,organization_id) references public.branches(id,organization_id) on delete restrict,foreign key(customer_id,organization_id) references public.sales_customers(id,organization_id) on delete restrict,foreign key(assigned_salesperson_id,organization_id) references public.organization_memberships(user_id,organization_id) on delete restrict,foreign key(revision_of_id,organization_id) references public.quotations(id,organization_id) on delete restrict,foreign key(converted_sale_id,organization_id) references public.sales_transactions(id,organization_id) on delete restrict);
create table public.quotation_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,quotation_id uuid not null,product_variant_id uuid not null,product_name text not null,variant_name text not null,sku text not null,unit text not null,quantity numeric(16,4) not null check(quantity>0),unit_price numeric(16,4) not null check(unit_price>=0),discount_amount numeric(16,4) not null default 0 check(discount_amount>=0),tax_type text not null check(tax_type in('inclusive','exclusive','exempt','zero_rated')),tax_rate numeric(7,4) not null default 0 check(tax_rate between 0 and 100),subtotal numeric(16,4) not null,tax_amount numeric(16,4) not null,total numeric(16,4) not null,position integer not null,unique(quotation_id,position),foreign key(quotation_id,organization_id) references public.quotations(id,organization_id) on delete cascade,foreign key(product_variant_id,organization_id) references public.product_variants(id,organization_id) on delete restrict);
create table public.quotation_audit_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null,quotation_id uuid not null,event text not null,actor_id uuid not null references auth.users(id),details jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(quotation_id,organization_id) references public.quotations(id,organization_id) on delete cascade);
create table public.quotation_shares(id uuid primary key default gen_random_uuid(),organization_id uuid not null,quotation_id uuid not null,channel text not null check(channel in('email','link')),recipient text,share_token uuid not null default gen_random_uuid() unique,delivery_status text not null default'queued' check(delivery_status in('queued','sent','failed','revoked')),failure_message text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),sent_at timestamptz,foreign key(quotation_id,organization_id) references public.quotations(id,organization_id) on delete cascade);
create table public.sales_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null,order_number text not null,quotation_id uuid not null,customer_id uuid not null,status text not null default'confirmed' check(status in('confirmed','processing','fulfilled','cancelled')),subtotal numeric(16,4) not null,discount_total numeric(16,4) not null,tax_total numeric(16,4) not null,total numeric(16,4) not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,order_number),unique(quotation_id),foreign key(branch_id,organization_id) references public.branches(id,organization_id),foreign key(quotation_id,organization_id) references public.quotations(id,organization_id),foreign key(customer_id,organization_id) references public.sales_customers(id,organization_id));
create table public.sales_order_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,sales_order_id uuid not null,product_variant_id uuid not null,product_name text not null,variant_name text not null,sku text not null,unit text not null,quantity numeric(16,4) not null,unit_price numeric(16,4) not null,discount_amount numeric(16,4) not null,tax_amount numeric(16,4) not null,total numeric(16,4) not null,position integer not null,foreign key(sales_order_id,organization_id) references public.sales_orders(id,organization_id) on delete cascade,foreign key(product_variant_id,organization_id) references public.product_variants(id,organization_id));
alter table public.quotations add foreign key(converted_sales_order_id,organization_id) references public.sales_orders(id,organization_id) on delete restrict;

create index quotations_list_idx on public.quotations(organization_id,branch_id,status,created_at desc);create index quotations_customer_idx on public.quotations(customer_id,created_at desc);create index quotation_lines_quote_idx on public.quotation_lines(quotation_id,position);create index quotation_audit_quote_idx on public.quotation_audit_history(quotation_id,created_at);create index quotation_shares_quote_idx on public.quotation_shares(quotation_id,created_at desc);create index sales_orders_list_idx on public.sales_orders(organization_id,branch_id,created_at desc);
create trigger set_updated_at before update on public.quotations for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.sales_orders for each row execute function private.set_updated_at();

create function private.quotation_module_enabled(requested_organization_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='quotations');$$;
alter table public.quotation_number_counters enable row level security;alter table public.quotations enable row level security;alter table public.quotation_lines enable row level security;alter table public.quotation_audit_history enable row level security;alter table public.quotation_shares enable row level security;alter table public.sales_orders enable row level security;alter table public.sales_order_lines enable row level security;
create policy quotations_read on public.quotations for select to authenticated using((select private.quotation_module_enabled(organization_id)) and private.can_business_permission(organization_id,'quotations.read',branch_id));
create policy quotation_lines_read on public.quotation_lines for select to authenticated using(exists(select 1 from public.quotations quote where quote.id=quotation_lines.quotation_id and quote.organization_id=quotation_lines.organization_id and private.quotation_module_enabled(quote.organization_id) and private.can_business_permission(quote.organization_id,'quotations.read',quote.branch_id)));
create policy quotation_audit_read on public.quotation_audit_history for select to authenticated using(exists(select 1 from public.quotations quote where quote.id=quotation_audit_history.quotation_id and quote.organization_id=quotation_audit_history.organization_id and private.can_business_permission(quote.organization_id,'quotations.read',quote.branch_id)));
create policy quotation_shares_read on public.quotation_shares for select to authenticated using(exists(select 1 from public.quotations quote where quote.id=quotation_shares.quotation_id and quote.organization_id=quotation_shares.organization_id and private.can_business_permission(quote.organization_id,'quotations.read',quote.branch_id)));
create policy sales_orders_read on public.sales_orders for select to authenticated using(private.can_business_permission(organization_id,'quotations.read',branch_id));
create policy sales_order_lines_read on public.sales_order_lines for select to authenticated using(exists(select 1 from public.sales_orders orders where orders.id=sales_order_lines.sales_order_id and orders.organization_id=sales_order_lines.organization_id and private.can_business_permission(orders.organization_id,'quotations.read',orders.branch_id)));
revoke all on public.quotation_number_counters,public.quotations,public.quotation_lines,public.quotation_audit_history,public.quotation_shares,public.sales_orders,public.sales_order_lines from public,anon,authenticated;grant select on public.quotations,public.quotation_lines,public.quotation_audit_history,public.quotation_shares,public.sales_orders,public.sales_order_lines to authenticated;

create function private.next_quotation_number(requested_organization_id uuid) returns text language plpgsql security definer set search_path='' as $$declare current_year integer:=extract(year from current_date);next_number integer;begin insert into public.quotation_number_counters(organization_id,year,last_number) values(requested_organization_id,current_year,1) on conflict(organization_id,year) do update set last_number=public.quotation_number_counters.last_number+1 returning last_number into next_number;return'QUO-'||current_year||'-'||lpad(next_number::text,6,'0');end;$$;
create function private.save_quotation(requested_organization_id uuid,requested_quotation_id uuid,requested_branch_id uuid,requested_customer_id uuid,requested_valid_until date,requested_notes text,requested_terms text,requested_salesperson_id uuid,requested_lines jsonb,requested_submit boolean) returns uuid language plpgsql security definer set search_path='' as $$
declare target_id uuid:=coalesce(requested_quotation_id,gen_random_uuid());actor uuid:=(select auth.uid());current_quote public.quotations%rowtype;item jsonb;variant public.product_variants%rowtype;product public.products%rowtype;qty numeric;price numeric;discount numeric;line_subtotal numeric;line_tax numeric;line_total numeric;subtotal_sum numeric:=0;discount_sum numeric:=0;tax_sum numeric:=0;total_sum numeric:=0;position_value integer:=0;quote_number text;threshold numeric:=10;approver_role text:='manager';approval_id uuid;discount_percent numeric:=0;
begin
 if actor is null or not private.quotation_module_enabled(requested_organization_id) or not private.can_business_permission(requested_organization_id,'quotations.manage',requested_branch_id) then raise exception'Permission denied.' using errcode='42501';end if;
 if jsonb_typeof(requested_lines)<>'array' or jsonb_array_length(requested_lines) not between 1 and 200 or requested_valid_until<current_date or char_length(coalesce(requested_notes,''))>4000 or char_length(coalesce(requested_terms,''))>8000 or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active) or not exists(select 1 from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id) or not exists(select 1 from public.organization_memberships where organization_id=requested_organization_id and user_id=requested_salesperson_id and status='active') then raise exception'Invalid quotation.' using errcode='22023';end if;
 if requested_quotation_id is not null then select*into current_quote from public.quotations where id=target_id and organization_id=requested_organization_id for update;if current_quote.id is null or current_quote.status<>'draft' or current_quote.approval_status='pending' then raise exception'Only an editable draft quotation can be changed.' using errcode='P0001';end if;quote_number:=current_quote.quotation_number;delete from public.quotation_lines where quotation_id=target_id;else quote_number:=private.next_quotation_number(requested_organization_id);insert into public.quotations(id,organization_id,branch_id,quotation_number,customer_id,assigned_salesperson_id,valid_until,notes,terms,created_by) values(target_id,requested_organization_id,requested_branch_id,quote_number,requested_customer_id,requested_salesperson_id,requested_valid_until,nullif(btrim(requested_notes),''),nullif(btrim(requested_terms),''),actor);end if;
 for item in select value from jsonb_array_elements(requested_lines) loop
  if item-array['productVariantId','quantity','unitPrice','discountAmount']::text[]<>'{}'::jsonb or not(item?&array['productVariantId','quantity','unitPrice','discountAmount']) then raise exception'Invalid quotation line.' using errcode='22023';end if;
  qty:=(item->>'quantity')::numeric;price:=(item->>'unitPrice')::numeric;discount:=(item->>'discountAmount')::numeric;select*into variant from public.product_variants where id=(item->>'productVariantId')::uuid and organization_id=requested_organization_id and status='active';select*into product from public.products where id=variant.product_id and organization_id=requested_organization_id and status='active';line_subtotal:=round(qty*price,4);if variant.id is null or product.id is null or qty<=0 or price<0 or discount<0 or discount>line_subtotal or(product.branch_id is not null and product.branch_id<>requested_branch_id) then raise exception'Invalid quotation line.' using errcode='22023';end if;line_tax:=case when product.tax_type='inclusive'and product.tax_rate>0 then round((line_subtotal-discount)*product.tax_rate/(100+product.tax_rate),4) when product.tax_type='exclusive' then round((line_subtotal-discount)*product.tax_rate/100,4) else 0 end;line_total:=case when product.tax_type='exclusive' then line_subtotal-discount+line_tax else line_subtotal-discount end;
  insert into public.quotation_lines(organization_id,quotation_id,product_variant_id,product_name,variant_name,sku,unit,quantity,unit_price,discount_amount,tax_type,tax_rate,subtotal,tax_amount,total,position) values(requested_organization_id,target_id,variant.id,product.name,variant.name,variant.sku,coalesce(variant.unit,product.default_unit),qty,price,discount,product.tax_type,product.tax_rate,line_subtotal,line_tax,line_total,position_value);position_value:=position_value+1;subtotal_sum:=subtotal_sum+line_subtotal;discount_sum:=discount_sum+discount;tax_sum:=tax_sum+line_tax;total_sum:=total_sum+line_total;
 end loop;
 update public.quotations set branch_id=requested_branch_id,customer_id=requested_customer_id,assigned_salesperson_id=requested_salesperson_id,valid_until=requested_valid_until,notes=nullif(btrim(requested_notes),''),terms=nullif(btrim(requested_terms),''),subtotal=subtotal_sum,discount_total=discount_sum,tax_total=tax_sum,total=total_sum,approval_status='not_required',approval_request_id=null where id=target_id;
 insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details) values(requested_organization_id,target_id,case when requested_quotation_id is null then'created'else'updated'end,actor,jsonb_build_object('total',total_sum,'lineCount',position_value));
 if requested_submit then
  if not private.can_business_permission(requested_organization_id,'quotations.send',requested_branch_id) then raise exception'Permission denied.' using errcode='42501';end if;select coalesce((module.config->>'discount_approval_percentage')::numeric,10),coalesce(nullif(module.config->>'discount_approver_role',''),'manager') into threshold,approver_role from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='quotations';discount_percent:=case when subtotal_sum>0 then discount_sum/subtotal_sum*100 else 0 end;
  if discount_percent>threshold then approval_id:=private.create_approval_request(requested_organization_id,'discount','Discount approval for '||quote_number,'Approve a '||round(discount_percent,2)||'% discount on '||quote_number,null,null,null,jsonb_build_array(jsonb_build_object('key','discount_review','name','Quotation discount review','approverRoleKey',approver_role)));update public.quotations set approval_status='pending',approval_request_id=approval_id where id=target_id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details) values(requested_organization_id,target_id,'approval_requested',actor,jsonb_build_object('discountPercentage',discount_percent,'threshold',threshold,'approvalRequestId',approval_id));
  else update public.quotations set status='sent',sent_at=now() where id=target_id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details) values(requested_organization_id,target_id,'sent',actor,jsonb_build_object('discountPercentage',discount_percent));end if;
 end if;return target_id;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid quotation data.' using errcode='22023';end;$$;

create function private.sync_quotation_approval() returns trigger language plpgsql security definer set search_path='' as $$declare quote_id uuid;begin if new.status is distinct from old.status and new.status in('approved','rejected','cancelled') then select id into quote_id from public.quotations where approval_request_id=new.id for update;if quote_id is not null then update public.quotations set approval_status=new.status,status=case when new.status='approved' then'sent'else'draft'end,sent_at=case when new.status='approved' then now()else sent_at end where id=quote_id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details) values(new.organization_id,quote_id,'approval_'||new.status,coalesce((select auth.uid()),new.requester_id),jsonb_build_object('approvalRequestId',new.id));end if;end if;return new;end;$$;
create trigger sync_quotation_approval after update of status on public.approval_requests for each row execute function private.sync_quotation_approval();

create function private.transition_quotation(requested_organization_id uuid,requested_quotation_id uuid,requested_status text) returns void language plpgsql security definer set search_path='' as $$declare quote public.quotations%rowtype;actor uuid:=(select auth.uid());begin select*into quote from public.quotations where id=requested_quotation_id and organization_id=requested_organization_id for update;if actor is null or quote.id is null or not private.can_business_permission(requested_organization_id,'quotations.manage',quote.branch_id) then raise exception'Permission denied.'using errcode='42501';end if;if not((quote.status='sent'and requested_status in('accepted','rejected'))or(quote.status='sent'and requested_status='expired'and quote.valid_until<current_date)) then raise exception'Invalid quotation transition.'using errcode='P0001';end if;update public.quotations set status=requested_status,accepted_at=case when requested_status='accepted'then now()end,rejected_at=case when requested_status='rejected'then now()end where id=quote.id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id) values(requested_organization_id,quote.id,requested_status,actor);end;$$;
create function private.copy_quotation(requested_organization_id uuid,requested_quotation_id uuid,requested_as_revision boolean) returns uuid language plpgsql security definer set search_path='' as $$declare source public.quotations%rowtype;target_id uuid:=gen_random_uuid();actor uuid:=(select auth.uid());new_number text;new_revision integer:=0;begin select*into source from public.quotations where id=requested_quotation_id and organization_id=requested_organization_id;if actor is null or source.id is null or not private.can_business_permission(requested_organization_id,'quotations.manage',source.branch_id) then raise exception'Permission denied.'using errcode='42501';end if;if requested_as_revision then new_number:=source.quotation_number;select coalesce(max(revision_number),-1)+1 into new_revision from public.quotations where organization_id=requested_organization_id and quotation_number=source.quotation_number;else new_number:=private.next_quotation_number(requested_organization_id);end if;insert into public.quotations(id,organization_id,branch_id,quotation_number,revision_number,revision_of_id,customer_id,assigned_salesperson_id,valid_until,notes,terms,subtotal,discount_total,tax_total,total,created_by) values(target_id,requested_organization_id,source.branch_id,new_number,new_revision,case when requested_as_revision then source.id end,source.customer_id,source.assigned_salesperson_id,greatest(source.valid_until,current_date),source.notes,source.terms,source.subtotal,source.discount_total,source.tax_total,source.total,actor);insert into public.quotation_lines(organization_id,quotation_id,product_variant_id,product_name,variant_name,sku,unit,quantity,unit_price,discount_amount,tax_type,tax_rate,subtotal,tax_amount,total,position) select organization_id,target_id,product_variant_id,product_name,variant_name,sku,unit,quantity,unit_price,discount_amount,tax_type,tax_rate,subtotal,tax_amount,total,position from public.quotation_lines where quotation_id=source.id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details) values(requested_organization_id,target_id,case when requested_as_revision then'revised'else'duplicated'end,actor,jsonb_build_object('sourceQuotationId',source.id));return target_id;end;$$;
create function private.convert_quotation_to_sale(requested_organization_id uuid,requested_quotation_id uuid,requested_location_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare quote public.quotations%rowtype;target_id uuid:=gen_random_uuid();actor uuid:=(select auth.uid());receipt text;line public.quotation_lines%rowtype;inventory_id uuid;begin select*into quote from public.quotations where id=requested_quotation_id and organization_id=requested_organization_id for update;if actor is null or quote.id is null or quote.status<>'accepted' or not private.can_business_permission(requested_organization_id,'quotations.convert',quote.branch_id) or not private.can_business_permission(requested_organization_id,'sales.create',quote.branch_id) or not private.pos_module_enabled(requested_organization_id) or not exists(select 1 from public.inventory_locations where id=requested_location_id and organization_id=requested_organization_id and branch_id=quote.branch_id and is_active) then raise exception'Quotation cannot be converted to a sale.'using errcode='P0001';end if;receipt:='POS-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(target_id::text,'-',''),1,8));insert into public.sales_transactions(id,organization_id,branch_id,inventory_location_id,customer_id,receipt_number,status,subtotal,discount_total,tax_total,total,client_transaction_id,client_created_at,created_by) values(target_id,requested_organization_id,quote.branch_id,requested_location_id,quote.customer_id,receipt,'suspended',quote.subtotal,quote.discount_total,quote.tax_total,quote.total,target_id,now(),actor);for line in select*from public.quotation_lines where quotation_id=quote.id order by position loop select item.id into inventory_id from public.inventory_items item where item.organization_id=requested_organization_id and item.product_variant_id=line.product_variant_id;insert into public.sales_lines(organization_id,sale_id,product_variant_id,inventory_item_id,product_name,variant_name,sku,quantity,unit_price,discount_amount,subtotal,tax_amount,total,unit_cost) select requested_organization_id,target_id,line.product_variant_id,inventory_id,line.product_name,line.variant_name,line.sku,line.quantity,line.unit_price,line.discount_amount,line.subtotal,line.tax_amount,line.total,coalesce(variant.cost_price,product.cost_price) from public.product_variants variant join public.products product on product.id=variant.product_id where variant.id=line.product_variant_id;end loop;insert into public.sales_audit_events(organization_id,sale_id,event,actor_id,details) values(requested_organization_id,target_id,'suspended',actor,jsonb_build_object('quotationId',quote.id));update public.quotations set status='converted',converted_sale_id=target_id,converted_at=now() where id=quote.id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details)values(requested_organization_id,quote.id,'converted_to_sale',actor,jsonb_build_object('saleId',target_id));return target_id;end;$$;
create function private.convert_quotation_to_sales_order(requested_organization_id uuid,requested_quotation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare quote public.quotations%rowtype;target_id uuid:=gen_random_uuid();actor uuid:=(select auth.uid());begin select*into quote from public.quotations where id=requested_quotation_id and organization_id=requested_organization_id for update;if actor is null or quote.id is null or quote.status<>'accepted' or not private.can_business_permission(requested_organization_id,'quotations.convert',quote.branch_id) then raise exception'Quotation cannot be converted to a sales order.'using errcode='P0001';end if;insert into public.sales_orders(id,organization_id,branch_id,order_number,quotation_id,customer_id,subtotal,discount_total,tax_total,total,created_by) values(target_id,requested_organization_id,quote.branch_id,'SO-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(target_id::text,'-',''),1,8)),quote.id,quote.customer_id,quote.subtotal,quote.discount_total,quote.tax_total,quote.total,actor);insert into public.sales_order_lines(organization_id,sales_order_id,product_variant_id,product_name,variant_name,sku,unit,quantity,unit_price,discount_amount,tax_amount,total,position) select requested_organization_id,target_id,product_variant_id,product_name,variant_name,sku,unit,quantity,unit_price,discount_amount,tax_amount,total,position from public.quotation_lines where quotation_id=quote.id;update public.quotations set status='converted',converted_sales_order_id=target_id,converted_at=now() where id=quote.id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details)values(requested_organization_id,quote.id,'converted_to_sales_order',actor,jsonb_build_object('salesOrderId',target_id));return target_id;end;$$;
create function private.queue_quotation_share(requested_organization_id uuid,requested_quotation_id uuid,requested_channel text,requested_recipient text) returns uuid language plpgsql security definer set search_path='' as $$declare quote public.quotations%rowtype;target_id uuid;actor uuid:=(select auth.uid());begin select*into quote from public.quotations where id=requested_quotation_id and organization_id=requested_organization_id;if actor is null or quote.id is null or not private.can_business_permission(requested_organization_id,'quotations.send',quote.branch_id) then raise exception'Permission denied.'using errcode='42501';end if;if requested_channel not in('email','link')or(requested_channel='email'and requested_recipient!~*'^[^@\s]+@[^@\s]+\.[^@\s]+$') then raise exception'Invalid share request.'using errcode='22023';end if;insert into public.quotation_shares(organization_id,quotation_id,channel,recipient,created_by) values(requested_organization_id,quote.id,requested_channel,nullif(lower(btrim(requested_recipient)),''),actor)returning id into target_id;insert into public.quotation_audit_history(organization_id,quotation_id,event,actor_id,details)values(requested_organization_id,quote.id,'share_queued',actor,jsonb_build_object('shareId',target_id,'channel',requested_channel));return target_id;end;$$;

