grant execute on function public.save_quotation(uuid,uuid,uuid,uuid,date,text,text,uuid,jsonb,boolean),public.transition_quotation(uuid,uuid,text),public.copy_quotation(uuid,uuid,boolean),public.convert_quotation_to_sale(uuid,uuid,uuid),public.convert_quotation_to_sales_order(uuid,uuid),public.queue_quotation_share(uuid,uuid,text,text) to authenticated;
create function private.reject_quotation_audit_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Quotation audit history is immutable.'using errcode='42501';end;$$;create trigger quotation_audit_immutable before update or delete on public.quotation_audit_history for each row execute function private.reject_quotation_audit_mutation();revoke all on function private.reject_quotation_audit_mutation()from public,anon,authenticated;
